package com.dpworld.fms.application;
import java.time.*; import java.util.*; import java.util.concurrent.*;
public final class TelemetryProcessor { private final ConcurrentMap<String,Instant> messages=new ConcurrentHashMap<>(),latest=new ConcurrentHashMap<>();private final Duration dedupeRetention; public TelemetryProcessor(Duration retention){dedupeRetention=retention;} public Result accept(String messageId,String assetId,Instant occurredAt,Instant now){messages.entrySet().removeIf(e->e.getValue().plus(dedupeRetention).isBefore(now));if(messages.putIfAbsent(messageId,now)!=null)return Result.DUPLICATE;var prior=latest.get(assetId);if(prior!=null&&occurredAt.isBefore(prior))return Result.OUT_OF_ORDER;latest.put(assetId,occurredAt);return Result.ACCEPTED;} public enum Result{ACCEPTED,DUPLICATE,OUT_OF_ORDER} }
